pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 depositAmt, uint256 collectAmt) public {
        // Keep amounts reasonable and positive
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > 0);
        // Avoid overflow in the reference
        vm.assume(depositAmt <= type(uint256).max / 2);

        // Initialize the contract: set MinSum and open it
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund the actor and make a deposit
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Record the actor's balance before Collect according to the reference
        uint256 beforeBalance = c.balances(actor);

        // Only attempt Collect if conditions hold
        if (beforeBalance >= collectAmt && beforeBalance >= c.MinSum()) {
            // Collect must be called by the actor with enough gas, no expectRevert
            vm.prank(actor);
            try c.Collect(collectAmt) {
                uint256 afterBalance = c.balances(actor);
                // General rule: after a successful Collect, the actor's balance decreases by exactly collectAmt
                assertTrue(afterBalance == beforeBalance - collectAmt);
            } catch {
                // If Collect reverted, the rule is not tested; skip
                assertTrue(true);
            }
        } else {
            // Conditions not met; skip
            assertTrue(true);
        }
    }
}

