pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address actor) public {
        // 1. Restrict to admissible domain
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(depositAmt > 0 && collectAmt > 0);
        bound(depositAmt, 1, 1e36);
        bound(collectAmt, 1, 1e36);
        // 2. Setup: initialize C, set MinSum to 0 to allow Collect, fund actor
        c.Initialized();
        c.SetMinSum(0);
        vm.deal(actor, depositAmt);
        // Record contract's ETH balance before any operations
        uint256 balBefore = address(c).balance;
        // Deposit from actor
        vm.prank(actor);
        c.Deposit{value: depositAmt}();
        // Record contract's ETH balance after Deposit
        uint256 balAfterDeposit = address(c).balance;
        // Collect from actor
        vm.prank(actor);
        c.Collect(collectAmt);
        // Record contract's ETH balance after Collect
        uint256 balAfterCollect = address(c).balance;
        // 3. GENERAL RULE: after Deposit+Collect, if collectAmt <= depositAmt, 
        // the contract's ETH balance must be strictly less than after Deposit.
        // In correct code, Deposit adds ether AND updates balance, so Collect can transfer;
        // in buggy code Deposit adds ether but does NOT update balance, so Collect is a no-op.
        // Therefore buggy: balAfterCollect == balAfterDeposit, correct: balAfterCollect < balAfterDeposit.
        if (collectAmt <= depositAmt) {
            assertTrue(balAfterCollect < balAfterDeposit);
        }
    }
}

