pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address user) public {
        vm.assume(user != address(0));
        vm.assume(user != address(c));
        depositAmt = bound(depositAmt, 1, type(uint256).max / 2);
        collectAmt = bound(collectAmt, 1, depositAmt - 1);

        // initialize
        c.SetMinSum(0);
        c.SetLogFile(address(0xFFfFfFffFFfffFFfFFfFFFFFffFFFffffFfFFFfF));
        c.Initialized();

        // first deposit
        vm.deal(user, depositAmt);
        vm.prank(user);
        c.Deposit{value: depositAmt}();

        // second deposit of an amount that will be overwritten by the bug
        vm.deal(user, 1);
        vm.prank(user);
        c.Deposit{value: 1}();

        // collect a portion
        vm.prank(user);
        c.Collect(collectAmt);

        uint256 finalBalance = c.balances(user);
        // expected balance: initial deposit (depositAmt) + second deposit (1) - collected (collectAmt)
        // bug sets balance to 1 on second deposit, so finalBalance would be 1 - collectAmt (revert) or 0 if collectAmt=1
        uint256 expected = (depositAmt + 1) - collectAmt;
        assertTrue(finalBalance == expected);
    }
}

