pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
        c.SetLogFile(address(0x1));
        c.Initialized();
    }

    function testFuzz_property(uint256 deposit1, uint256 collectAmt, uint256 deposit2) public {
        // Bound to avoid overflow and ensure collectAmt <= deposit1
        deposit1 = bound(deposit1, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 1, type(uint128).max);
        deposit2 = bound(deposit2, 1, type(uint128).max);

        vm.assume(collectAmt <= deposit1);
        vm.assume(deposit1 >= c.MinSum());
        vm.assume(collectAmt >= c.MinSum());

        // Fund and deposit from the reverter contract
        vm.deal(address(reverter), deposit1 + deposit2);
        vm.startPrank(address(reverter));
        c.Deposit{value: deposit1}();
        vm.stopPrank();

        // Attempt a collect that will revert because Reverter's receive reverts
        vm.startPrank(address(reverter));
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // After revert, deposit again
        vm.startPrank(address(reverter));
        c.Deposit{value: deposit2}();
        vm.stopPrank();

        // The reference should preserve balance: deposit1 + deposit2,
        // because the collect reverted and the second deposit adds.
        // The bug overwrites balance with deposit2, breaking the invariant
        // that balance reflects total deposited minus only successfully collected amounts.
        assertEq(c.balances(address(reverter)), deposit1 + deposit2);
    }
}

